package dev.bennett.codexmeter;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.concurrent.*;
/** Actual foreground preference observer; never refreshes a real account or grants rewards. */
public final class Stable311HomeNativeTest extends Instrumentation {
 int checks;Throwable failure;void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 void main(Runnable r){runOnMainSync(()->{try{r.run();}catch(Throwable e){failure=e;}});if(failure!=null){Throwable e=failure;failure=null;throw new AssertionError(e);}}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 UsageSnapshot sample(double used,long at){return new UsageSnapshot("plus",true,false,new UsageWindow(25.25,18000,0,(at+7200000)/1000),new UsageWindow(used,604800,0,(at+3*86400000L)/1000),at);}
 void shown(MainActivity a,UsageSnapshot expected)throws Exception{for(int i=0;i<100;i++){boolean[] ready={false};main(()->{View root=a.findViewById(android.R.id.content);TextView used=root.findViewWithTag("beta999:weekly-used"),remaining=root.findViewWithTag("beta998:quota:weekly:value");ready[0]=used!=null&&remaining!=null&&used.getText().toString().contains(UsagePrecision.used(expected.weekly,AppPreferences.usageDecimalPlaces(a)))&&remaining.getText().toString().equals(UsagePrecision.remaining(expected.weekly,AppPreferences.usageDecimalPlaces(a)));});if(ready[0]){check(true,"Used and remaining update from the same background snapshot");return;}Thread.sleep(50);}throw new AssertionError("Stale/mixed weekly display");}
 @Override public void onStart(){Context c=getTargetContext();Bundle result=new Bundle();int code=0;MainActivity home=null;UsageSnapshot original=null;String oldError=null,oldPreset=null;try{
  check(Build.MODEL.contains("sdk")&&c.getPackageName().equals("dev.bennett.codexmeter")&&"stable311-qa".equals(SecureTokenStore.load(c).accountId),"Owned stable synthetic only");check(c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName.equals("3.1.1"),"Installed stable3.1.1");original=AppPreferences.loadSnapshot(c);oldError=AppPreferences.getLastError(c);oldPreset=BetaPreferences.preset(c);AppPreferences.setLastError(c,"");String account=SubscriptionStore.accountKey(c),tokens=SecureTokenStore.load(c).toJson().toString();long xp=BetaGrowthStore.load(c,account).getLong("total"),now=System.currentTimeMillis();UsageSnapshot first=sample(66.75,now);AppPreferences.saveSnapshot(c,first);
  home=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));MainActivity screen=home;shown(screen,first);
  for(String preset:new String[]{"simple","growth","detail"}){BetaPreferences.prefs(c).edit().putString("preset",preset).commit();main(screen::rebuild);shown(screen,first);main(()->{View root=screen.findViewById(android.R.id.content);ViewGroup summary=root.findViewWithTag("beta999:summary");View weekly=root.findViewWithTag("beta999:weekly");check(summary!=null&&weekly!=null,"Stable primary surfaces "+preset);ViewGroup parent=(ViewGroup)summary.getParent();check(parent.indexOfChild(summary)==0&&parent.indexOfChild(weekly)==parent.indexOfChild(summary)+2,"Summary immediately followed by weekly usage");check(root.findViewWithTag("beta998:focus")==null,"No home now-task card");check(root.findViewWithTag("beta996:tier-badge")!=null&&root.findViewWithTag("beta996:level")!=null,"Tier and level retained");});}
  ExecutorService worker=Executors.newSingleThreadExecutor();try{int index=1;for(double used:new double[]{47.25,0,100,66.75}){UsageSnapshot next=sample(used,now+index++);check(worker.submit(()->AppPreferences.saveSnapshot(c,next)).get(),"Background preference commit without broadcast");shown(screen,next);}}finally{worker.shutdownNow();}
  AppPreferences.setLastError(c,"SYNTHETIC_OFFLINE");main(screen::rebuild);shown(screen,sample(66.75,now+4));main(()->{TextView status=screen.findViewById(android.R.id.content).findViewWithTag("beta998:quota:weekly:status");check(status.getText().toString().equals(screen.getString(R.string.phase_a_cached_failed)),"Cached failure state retained");});
  AppPreferences.setLastError(c,"");AppPreferences.saveSnapshot(c,new UsageSnapshot("free",true,false,null,null,now+5));main(screen::rebuild);main(()->{TextView remaining=screen.findViewById(android.R.id.content).findViewWithTag("beta998:quota:weekly:value");check(remaining.getText().toString().equals("—"),"Missing window remains unknown, not zero/full");});
  check(BetaGrowthStore.load(c,account).getLong("total")==xp,"Home changes award no XP");check(SecureTokenStore.load(c).toJson().toString().equals(tokens),"Home changes preserve authentication");
  result.putString("stream","Stable311 home: "+checks+" checks passed; background snapshot updates,all presets,0/missing/offline,same-snapshot quota consistency; synthetic only.\n");code=-1;
 }catch(Throwable error){result.putString("stream",android.util.Log.getStackTraceString(error));}finally{try{if(home!=null){MainActivity screen=home;main(screen::finish);}if(original!=null)AppPreferences.saveSnapshot(c,original);if(oldError!=null)AppPreferences.setLastError(c,oldError);if(oldPreset!=null)BetaPreferences.prefs(c).edit().putString("preset",oldPreset).commit();}catch(Throwable cleanup){code=0;result.putString("stream",result.getString("stream","")+cleanup);}}finish(code,result);}
}
